source='''from collections import deque

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    seen=set()
    comps=[]
    for r in range(h):
        for c in range(w):
            color=a[r][c]
            if not color or (r,c) in seen:
                continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and a[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            top=min(x for x,y in cells); left=min(y for x,y in cells)
            shape=frozenset((x-top,y-left) for x,y in cells)
            comps.append((color,cells,shape))
    references={}
    for color,cells,shape in comps:
        if color!=1:
            references.setdefault(shape,color)
    for color,cells,shape in comps:
        if color==1 and shape in references:
            new=references[shape]
            for x,y in cells:
                a[x][y]=new
    return a
'''
